CREATE OR REPLACE VIEW sv_higher_education.dq_hed__freshness AS
/*
  Data Quality Component: Freshness Checks
  
  Purpose: Monitor data freshness and staleness
  
  Checks:
  - Most recent update timestamp
  - Oldest update timestamp
  - Hours since last update
  - Days since last update
  - Freshness status classification
  - Records over 7 days old
  - Current records percentage
*/

with source_data as (
    select * from sv_higher_education.stg_hed__students
),

freshness_metrics as (
    select
        'Data Freshness' as quality_dimension,
        max(last_updated) as most_recent_update,
        min(last_updated) as oldest_update,
        datediff('hour', max(last_updated), current_timestamp()) as hours_since_last_update,
        datediff('day', max(last_updated), current_timestamp()) as days_since_last_update,
        
        case
            when datediff('hour', max(last_updated), current_timestamp()) <= 1 then 'Excellent'
            when datediff('hour', max(last_updated), current_timestamp()) <= 6 then 'Good'
            when datediff('hour', max(last_updated), current_timestamp()) <= 24 then 'Acceptable'
            when datediff('day', max(last_updated), current_timestamp()) <= 3 then 'Needs Attention'
            else 'Stale Data'
        end as freshness_status,
        
        -- Check for stale individual records
        count(case when datediff('day', last_updated, current_timestamp()) > 7 then 1 end) as records_over_7_days_old,
        round(
            count(case when datediff('day', last_updated, current_timestamp()) <= 7 then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as records_current_pct
    from source_data
)

select * from freshness_metrics;
COMMENT ON VIEW sv_higher_education.dq_hed__freshness IS 'Data quality component that monitors data freshness and staleness. Tracks most recent updates, calculates hours/days since last update, and identifies stale records.';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN QUALITY_DIMENSION COMMENT 'Quality dimension identifier (Data Freshness)';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN MOST_RECENT_UPDATE COMMENT 'Timestamp of most recent data update';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN OLDEST_UPDATE COMMENT 'Timestamp of oldest data update';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN HOURS_SINCE_LAST_UPDATE COMMENT 'Hours elapsed since last update';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN DAYS_SINCE_LAST_UPDATE COMMENT 'Days elapsed since last update';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN FRESHNESS_STATUS COMMENT 'Freshness classification (Excellent/Good/Acceptable/Needs Attention/Stale)';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN RECORDS_OVER_7_DAYS_OLD COMMENT 'Count of records not updated in 7+ days';
ALTER VIEW sv_higher_education.dq_hed__freshness MODIFY COLUMN RECORDS_CURRENT_PCT COMMENT 'Percentage of records updated within 7 days';

CREATE OR REPLACE VIEW sv_higher_education.dq_hed__validity AS
/*
  Data Quality Component: Validity Checks
  
  Purpose: Validate data ranges and logical consistency
  
  Checks:
  - GPA validity (0.0 - 4.0)
  - Credit hours validity (earned <= attempted)
  - Course completion rate validity (0.0 - 1.0)
  - Engagement score validity (0 - 100)
  - Assignment score validity (0 - 100)
  - Financial aid validity (non-negative)
  - Date logic validity (enrollment <= last_login)
  - Overall validity score
*/

with source_data as (
    select * from sv_higher_education.stg_hed__students
),

validity_metrics as (
    select
        'Data Validity' as quality_dimension,
        
        -- GPA validity (should be between 0.0 and 4.0)
        count(case when current_gpa < 0.0 or current_gpa > 4.0 then 1 end) as invalid_gpa_records,
        round(
            count(case when current_gpa >= 0.0 and current_gpa <= 4.0 then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as gpa_validity_pct,
        
        -- Credit hours validity (earned should not exceed attempted)
        count(case when credit_hours_earned > credit_hours_attempted then 1 end) as invalid_credit_hour_records,
        round(
            count(case when credit_hours_earned <= credit_hours_attempted then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as credit_hours_validity_pct,
        
        -- Course completion rate validity (should be between 0.0 and 1.0)
        count(case when course_completion_rate < 0.0 or course_completion_rate > 1.0 then 1 end) as invalid_completion_rate_records,
        round(
            count(case when course_completion_rate >= 0.0 and course_completion_rate <= 1.0 then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as completion_rate_validity_pct,
        
        -- Engagement score validity (should be between 0 and 100)
        count(case when engagement_score < 0 or engagement_score > 100 then 1 end) as invalid_engagement_score_records,
        round(
            count(case when engagement_score >= 0 and engagement_score <= 100 then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as engagement_score_validity_pct,
        
        -- Assignment score validity (should be between 0 and 100)
        count(case when avg_assignment_score < 0 or avg_assignment_score > 100 then 1 end) as invalid_assignment_score_records,
        round(
            count(case when avg_assignment_score >= 0 and avg_assignment_score <= 100 then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as assignment_score_validity_pct,
        
        -- Financial aid validity (should be non-negative)
        count(case when financial_aid_amount < 0 then 1 end) as invalid_financial_aid_records,
        round(
            count(case when financial_aid_amount >= 0 then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as financial_aid_validity_pct,
        
        -- Date logic validity (enrollment should be before last login)
        count(case when enrollment_date > last_login_date then 1 end) as invalid_date_logic_records,
        round(
            count(case when enrollment_date <= last_login_date then 1 end)::decimal 
            / nullif(count(*), 0) * 100,
            2
        ) as date_logic_validity_pct,
        
        -- Overall validity score
        round(
            (
                (count(case when current_gpa >= 0.0 and current_gpa <= 4.0 then 1 end)::decimal / nullif(count(*), 0)) +
                (count(case when credit_hours_earned <= credit_hours_attempted then 1 end)::decimal / nullif(count(*), 0)) +
                (count(case when course_completion_rate >= 0.0 and course_completion_rate <= 1.0 then 1 end)::decimal / nullif(count(*), 0)) +
                (count(case when engagement_score >= 0 and engagement_score <= 100 then 1 end)::decimal / nullif(count(*), 0)) +
                (count(case when financial_aid_amount >= 0 then 1 end)::decimal / nullif(count(*), 0))
            ) / 5.0 * 100,
            1
        ) as overall_validity_score
    from source_data
)

select * from validity_metrics;
COMMENT ON VIEW sv_higher_education.dq_hed__validity IS 'Data quality component that validates data ranges and logical consistency. Checks GPA bounds, credit hour logic, completion rate bounds, engagement score bounds, financial aid validity, and date logic.';
ALTER VIEW sv_higher_education.dq_hed__validity MODIFY COLUMN QUALITY_DIMENSION COMMENT 'Quality dimension identifier (Data Validity)';
ALTER VIEW sv_higher_education.dq_hed__validity MODIFY COLUMN INVALID_GPA_RECORDS COMMENT 'Count of records with GPA outside 0.0-4.0 range';
ALTER VIEW sv_higher_education.dq_hed__validity MODIFY COLUMN GPA_VALIDITY_PCT COMMENT 'Percentage of records with valid GPA';
ALTER VIEW sv_higher_education.dq_hed__validity MODIFY COLUMN INVALID_CREDIT_HOUR_RECORDS COMMENT 'Count of records where earned > attempted';
ALTER VIEW sv_higher_education.dq_hed__validity MODIFY COLUMN CREDIT_HOURS_VALIDITY_PCT COMMENT 'Percentage of records with valid credit hours';
ALTER VIEW sv_higher_education.dq_hed__validity MODIFY COLUMN OVERALL_VALIDITY_SCORE COMMENT 'Overall validity score (0-100)';

CREATE OR REPLACE VIEW sv_higher_education.int_hed__engagement_categories AS
/*
  Intermediate Model: Student Engagement Categories
  
  Purpose: Centralized engagement categorization logic used by multiple downstream models
  
  Engagement Dimensions:
  - Login Recency Category
  - Course Views Category
  - Assignment Activity Category
  - Assignment Performance Category
  - Discussion Participation Category
  - Engagement Level
  - Engagement Balance Score
  
  Used By:
  - vw_hed_engagement_analytics
  - vw_hed_retention_risk_analysis
*/

with students as (
    select * from sv_higher_education.stg_hed__students
),

engagement_calculations as (
    select
        -- Pass through identifiers
        student_id,
        record_id,
        advisor_id,
        major_code,
        academic_standing,
        at_risk_flag,
        
        -- Pass through metrics
        current_gpa,
        course_completion_rate,
        engagement_score,
        total_course_views,
        assignment_submissions,
        avg_assignment_score,
        discussion_posts,
        intervention_count,
        enrollment_date,
        last_login_date,
        last_updated,
        days_since_last_login,
        days_active_since_enrollment,
        
        -- Login Recency Category
        case
            when days_since_last_login = 0 then 'Today'
            when days_since_last_login <= 1 then 'Within 24 Hours'
            when days_since_last_login <= 3 then 'Within 3 Days'
            when days_since_last_login <= 7 then 'Within 1 Week'
            when days_since_last_login <= 14 then 'Within 2 Weeks'
            else 'Over 2 Weeks Ago'
        end as login_recency_category,
        
        -- Course Views Category
        case
            when total_course_views >= 300 then 'Very High'
            when total_course_views >= 200 then 'High'
            when total_course_views >= 100 then 'Moderate'
            when total_course_views >= 50 then 'Low'
            else 'Very Low'
        end as course_views_category,
        
        -- Assignment Activity Category
        case
            when assignment_submissions >= 18 then 'Very Active'
            when assignment_submissions >= 14 then 'Active'
            when assignment_submissions >= 10 then 'Moderate'
            when assignment_submissions >= 6 then 'Low'
            else 'Very Low'
        end as assignment_activity_category,
        
        -- Assignment Performance Category
        case
            when avg_assignment_score >= 85 then 'Excellent'
            when avg_assignment_score >= 75 then 'Good'
            when avg_assignment_score >= 65 then 'Satisfactory'
            when avg_assignment_score >= 50 then 'Needs Improvement'
            else 'Critical'
        end as assignment_performance_category,
        
        -- Discussion Participation Category
        case
            when discussion_posts >= 25 then 'Very Active'
            when discussion_posts >= 15 then 'Active'
            when discussion_posts >= 8 then 'Moderate'
            when discussion_posts >= 3 then 'Low'
            else 'Minimal'
        end as discussion_participation_category,
        
        -- Overall Engagement Level
        case
            when engagement_score >= 80 then 'Highly Engaged'
            when engagement_score >= 60 then 'Engaged'
            when engagement_score >= 40 then 'Moderately Engaged'
            when engagement_score >= 20 then 'Disengaged'
            else 'Critically Disengaged'
        end as engagement_level,
        
        -- Engagement Balance Score (measures diverse engagement across dimensions)
        round(
            (
                (total_course_views / 400.0 * 100) +  -- Normalize to 0-100
                (assignment_submissions / 25.0 * 100) +
                (discussion_posts / 35.0 * 100)
            ) / 3.0,
            1
        ) as engagement_balance_score

    from students
),

final as (
    select
        *,
        -- Engagement vs Performance Quadrant Analysis
        case
            when engagement_score >= 60 and current_gpa >= 3.0 
            then 'High Engagement / High Performance'
            
            when engagement_score >= 60 and current_gpa < 3.0 
            then 'High Engagement / Low Performance'
            
            when engagement_score < 60 and current_gpa >= 3.0 
            then 'Low Engagement / High Performance'
            
            else 'Low Engagement / Low Performance'
        end as engagement_performance_quadrant,
        
        -- Engagement Trend Concerns
        case
            when days_since_last_login > 14 
                and engagement_score < 40 
            then 'Immediate Concern - Student Dropout Risk'
            
            when days_since_last_login > 7 
                and engagement_score < 50 
            then 'Elevated Concern - Declining Engagement'
            
            when engagement_score < 30 
            then 'High Concern - Critically Disengaged'
            
            when assignment_submissions < 5 
                and discussion_posts < 3 
            then 'Moderate Concern - Minimal Participation'
            
            else 'No Immediate Concern'
        end as engagement_concern_level,
        
        -- Recommended Engagement Actions
        case
            when days_since_last_login > 14 
            then 'Immediate outreach required; Check student wellness'
            
            when engagement_score < 30 
            then 'Schedule advisor meeting; Review barriers to engagement'
            
            when assignment_submissions < 5 
            then 'Connect with instructor; Offer tutoring support'
            
            when discussion_posts < 3 
            then 'Encourage peer collaboration; Review discussion participation expectations'
            
            when engagement_score >= 80 
            then 'Acknowledge engagement; Consider peer mentor role'
            
            else 'Monitor ongoing; Maintain regular touchpoints'
        end as recommended_engagement_action
        
    from engagement_calculations
)

select * from final;
COMMENT ON VIEW sv_higher_education.int_hed__engagement_categories IS 'Intermediate model providing centralized engagement categorization logic. Calculates login recency, course views, assignment activity, discussion participation, and engagement levels used by downstream engagement analytics models.';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN STUDENT_ID COMMENT 'Unique student identifier';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN LOGIN_RECENCY_CATEGORY COMMENT 'Categorical description of login recency (Today, Within 24 Hours, etc.)';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN COURSE_VIEWS_CATEGORY COMMENT 'Course viewing behavior category (Very High/High/Moderate/Low/Very Low)';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN ASSIGNMENT_ACTIVITY_CATEGORY COMMENT 'Assignment submission activity level';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN ASSIGNMENT_PERFORMANCE_CATEGORY COMMENT 'Assignment score performance category';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN DISCUSSION_PARTICIPATION_CATEGORY COMMENT 'Discussion forum participation level';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN ENGAGEMENT_LEVEL COMMENT 'Overall engagement classification (Highly Engaged to Critically Disengaged)';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN ENGAGEMENT_BALANCE_SCORE COMMENT 'Normalized score measuring diversity of engagement across dimensions';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN ENGAGEMENT_PERFORMANCE_QUADRANT COMMENT 'Classification combining engagement and academic performance';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN ENGAGEMENT_CONCERN_LEVEL COMMENT 'Urgency classification for engagement-related concerns';
ALTER VIEW sv_higher_education.int_hed__engagement_categories MODIFY COLUMN RECOMMENDED_ENGAGEMENT_ACTION COMMENT 'Specific recommended actions based on engagement profile';

CREATE OR REPLACE VIEW sv_higher_education.int_hed__risk_levels AS
/*
  Intermediate Model: Student Risk Levels
  
  Purpose: Centralized risk categorization logic used by multiple downstream models
  
  Risk Dimensions:
  - GPA Risk Level
  - Completion Risk Level
  - Engagement Risk Level
  - Login Recency Risk Level
  - Overall Risk Assessment
  
  Used By:
  - vw_hed_retention_risk_analysis
  - vw_hed_data_quality (anomaly detection)
*/

with students as (
    select * from sv_higher_education.stg_hed__students
),

risk_calculations as (
    select
        -- Pass through identifiers
        student_id,
        record_id,
        advisor_id,
        major_code,
        academic_standing,
        at_risk_flag,
        
        -- Pass through metrics for downstream use
        current_gpa,
        course_completion_rate,
        engagement_score,
        days_since_last_login,
        total_course_views,
        assignment_submissions,
        discussion_posts,
        financial_aid_amount,
        intervention_count,
        plagiarism_incidents,
        writing_quality_score,
        enrollment_date,
        last_login_date,
        last_updated,
        
        -- GPA Risk Level
        case
            when current_gpa < 2.0 then 'Critical'
            when current_gpa < 2.5 then 'High'
            when current_gpa < 3.0 then 'Moderate'
            else 'Low'
        end as gpa_risk_level,
        
        -- Completion Risk Level
        case
            when course_completion_rate < 0.50 then 'Critical'
            when course_completion_rate < 0.70 then 'High'
            when course_completion_rate < 0.85 then 'Moderate'
            else 'Low'
        end as completion_risk_level,
        
        -- Engagement Risk Level
        case
            when engagement_score < 30 then 'Critical'
            when engagement_score < 50 then 'High'
            when engagement_score < 70 then 'Moderate'
            else 'Low'
        end as engagement_risk_level,
        
        -- Login Recency Risk Level
        case
            when days_since_last_login > 14 then 'Critical'
            when days_since_last_login > 7 then 'High'
            when days_since_last_login > 3 then 'Moderate'
            else 'Low'
        end as login_recency_risk_level,
        
        -- Financial Aid Category
        case
            when financial_aid_amount = 0 then 'No Aid'
            when financial_aid_amount < 10000 then 'Partial Aid'
            else 'Full Support'
        end as financial_aid_category,
        
        -- Intervention Category
        case
            when intervention_count >= 5 then 'High Intervention'
            when intervention_count >= 2 then 'Moderate Intervention'
            when intervention_count > 0 then 'Low Intervention'
            else 'No Intervention'
        end as intervention_category

    from students
),

final as (
    select
        *,
        -- Overall Risk Assessment (composite of all risk dimensions)
        case
            -- Critical: ANY dimension is Critical
            when gpa_risk_level = 'Critical'
                or completion_risk_level = 'Critical'
                or engagement_risk_level = 'Critical'
                or login_recency_risk_level = 'Critical'
            then 'Critical - Immediate Intervention'
            
            -- High: ANY dimension is High (and no Critical)
            when gpa_risk_level = 'High'
                or completion_risk_level = 'High'
                or engagement_risk_level = 'High'
                or login_recency_risk_level = 'High'
            then 'High - Priority Attention'
            
            -- Moderate: ANY dimension is Moderate (and no Critical or High)
            when gpa_risk_level = 'Moderate'
                or completion_risk_level = 'Moderate'
                or engagement_risk_level = 'Moderate'
                or login_recency_risk_level = 'Moderate'
            then 'Moderate - Monitor Closely'
            
            -- Low: All dimensions are Low
            else 'Low - Standard Support'
        end as overall_risk_assessment,
        
        -- Recommended Actions based on risk profile
        case
            when gpa_risk_level = 'Critical'
                or completion_risk_level = 'Critical'
                or engagement_risk_level = 'Critical'
                or login_recency_risk_level = 'Critical'
            then 'Schedule mandatory advisor meeting; Review academic plan; Connect with tutoring/counseling; Verify financial aid status'
            
            when gpa_risk_level = 'High'
                or completion_risk_level = 'High'
                or engagement_risk_level = 'High'
                or login_recency_risk_level = 'High'
            then 'Advisor check-in within 1 week; Offer academic support resources; Review course load'
            
            when gpa_risk_level = 'Moderate'
                or completion_risk_level = 'Moderate'
                or engagement_risk_level = 'Moderate'
                or login_recency_risk_level = 'Moderate'
            then 'Monitor engagement metrics; Send supportive communication; Track attendance patterns'
            
            else 'Continue standard support; Celebrate successes; Maintain engagement'
        end as recommended_action
        
    from risk_calculations
)

select * from final;
COMMENT ON VIEW sv_higher_education.int_hed__risk_levels IS 'Intermediate model providing centralized risk categorization logic. Calculates GPA risk, completion risk, engagement risk, login recency risk, and overall risk assessment used by downstream retention analysis models.';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN STUDENT_ID COMMENT 'Unique student identifier';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN GPA_RISK_LEVEL COMMENT 'Risk categorization based on GPA (Critical/High/Moderate/Low)';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN COMPLETION_RISK_LEVEL COMMENT 'Risk categorization based on course completion rate';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN ENGAGEMENT_RISK_LEVEL COMMENT 'Risk categorization based on engagement score';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN LOGIN_RECENCY_RISK_LEVEL COMMENT 'Risk categorization based on days since last login';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN FINANCIAL_AID_CATEGORY COMMENT 'Financial aid classification (No Aid/Partial Aid/Full Support)';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN INTERVENTION_CATEGORY COMMENT 'Intervention frequency classification';
ALTER VIEW sv_higher_education.int_hed__risk_levels MODIFY COLUMN OVERALL_RISK_ASSESSMENT COMMENT 'Composite risk level combining all dimensions';
