CREATE OR REPLACE TABLE sv_higher_education.metricflow_time_spine AS
-- models/metricflow_time_spine.sql
-- This model creates a time spine table required by the dbt Semantic Layer
-- It generates a row for each day/hour/etc to support time-based metric queries



WITH date_spine AS (
  





with rawdata as (

    

    

    with p as (
        select 0 as generated_number union all select 1
    ), unioned as (

    select

    
    p0.generated_number * power(2, 0)
     + 
    
    p1.generated_number * power(2, 1)
     + 
    
    p2.generated_number * power(2, 2)
     + 
    
    p3.generated_number * power(2, 3)
     + 
    
    p4.generated_number * power(2, 4)
     + 
    
    p5.generated_number * power(2, 5)
     + 
    
    p6.generated_number * power(2, 6)
     + 
    
    p7.generated_number * power(2, 7)
     + 
    
    p8.generated_number * power(2, 8)
     + 
    
    p9.generated_number * power(2, 9)
     + 
    
    p10.generated_number * power(2, 10)
     + 
    
    p11.generated_number * power(2, 11)
    
    
    + 1
    as generated_number

    from

    
    p as p0
     cross join 
    
    p as p1
     cross join 
    
    p as p2
     cross join 
    
    p as p3
     cross join 
    
    p as p4
     cross join 
    
    p as p5
     cross join 
    
    p as p6
     cross join 
    
    p as p7
     cross join 
    
    p as p8
     cross join 
    
    p as p9
     cross join 
    
    p as p10
     cross join 
    
    p as p11
    
    

    )

    select *
    from unioned
    where generated_number <= 4017
    order by generated_number



),

all_periods as (

    select (
        

    dateadd(
        day,
        row_number() over (order by 1) - 1,
        cast('2020-01-01' as date)
        )


    ) as date_day
    from rawdata

),

filtered as (

    select *
    from all_periods
    where date_day <= cast('2030-12-31' as date)

)

select * from filtered


)

SELECT
  date_day AS date_day
FROM date_spine;
COMMENT ON TABLE sv_higher_education.metricflow_time_spine IS 'Time spine table for MetricFlow. Contains one row per day.';
COMMENT ON COLUMN sv_higher_education.metricflow_time_spine.DATE_DAY IS 'The date dimension at daily grain';

CREATE OR REPLACE VIEW sv_higher_education.vw_hed_retention_risk_analysis AS
/*
  Student Retention Risk Analysis
  
  Purpose: Identify and analyze students at risk of dropping out
  
  Risk Factors Analyzed:
  - Academic standing (probation, warning, suspension)
  - Low engagement (course views, assignment submissions)
  - Poor completion rates
  - Financial aid needs
  - Intervention history
  
  Use Cases:
  - Early warning system for advisors
  - Targeted intervention planning
  - Retention program effectiveness
  
  Dependencies:
  - int_hed__risk_levels (provides all risk categorizations)
*/

with risk_data as (
    select * from sv_higher_education.int_hed__risk_levels
)

select
    student_id,
    major_code,
    advisor_id,
    academic_standing,
    at_risk_flag,
    
    -- Academic Risk Factors
    current_gpa,
    gpa_risk_level,
    course_completion_rate,
    completion_risk_level,
    
    -- Engagement Risk Factors
    engagement_score,
    engagement_risk_level,
    total_course_views,
    assignment_submissions,
    discussion_posts,
    days_since_last_login,
    login_recency_risk_level,
    
    -- Financial Risk Factors
    financial_aid_amount,
    financial_aid_category,
    
    -- Intervention History
    intervention_count,
    intervention_category,
    
    -- Academic Integrity
    plagiarism_incidents,
    writing_quality_score,
    
    -- Overall Risk Assessment
    overall_risk_assessment,
    recommended_action,
    
    -- Dates
    enrollment_date,
    last_login_date,
    last_updated
from risk_data
-- Filter to at-risk students only
-- Note: Adjust the WHERE clause based on how your data stores boolean values
--   Option 1 (boolean): WHERE at_risk_flag = true
--   Option 2 (string):  WHERE UPPER(at_risk_flag::VARCHAR) = 'TRUE'
--   Option 3 (all):     Remove WHERE clause to see all students with risk analysis
where at_risk_flag = true 
   or UPPER(at_risk_flag::VARCHAR) = 'TRUE'
order by 
  case overall_risk_assessment
    when 'Critical - Immediate Intervention' then 1
    when 'High - Priority Attention' then 2
    when 'Moderate - Monitor Closely' then 3
    else 4
  end,
  current_gpa asc,
  engagement_score asc;
COMMENT ON VIEW sv_higher_education.vw_hed_retention_risk_analysis IS 'Detailed student-level retention risk analysis identifying at-risk students with risk factors, risk levels, and recommended interventions. Filters to show only at-risk students, ordered by severity.';
